    private static String normalized(String path){return path.replaceFirst("^patch/","").replaceAll("/@(?:before|after)?[0-9]+(?=/|$)","/@").replaceAll("/\\+$","");}
    private static Set<String> components(SchemaDocument doc,String namespace){Set<String> result=new LinkedHashSet<>();SchemaDocument.Node engine=doc.root.child("engine");if(engine==null)return result;for(SchemaDocument.Node l:engine.children)for(SchemaDocument.Node n:l.children){if(!n.scalar())continue;String v=n.value;int i=v.indexOf('@');if(i>0&&v.substring(i+1).equals(namespace))result.add(v.substring(0,i));if(i<0&&namespace.equals("translator")&&(v.equals("script_translator")||v.equals("table_translator")))result.add(v);}return result;}
    private static boolean translation(String c){return c.equals("script_translator")||c.equals("table_translator");}
    static Field get(SchemaDocument doc,String path){String p=normalized(path);Field field=fields.get(p);if(field!=null)return field;int i=p.indexOf('/');if(i>=0){String ns=p.substring(0,i),suffix=p.substring(i);for(String c:components(doc,ns)){field=fields.get(c+suffix);if(field==null&&translation(c))field=fields.get("translator"+suffix);if(field!=null)return field;}}if(p.endsWith("/__include"))return fields.get("__include");if(p.endsWith("/__patch"))return fields.get("__patch");if(p.startsWith("ascii_composer/switch_key/"))return new Field("切换方式","inline_ascii / commit_text / commit_code / clear / set_ascii_mode / unset_ascii_mode；具体支持取决于引擎版本",STRING,CORE+"gear/ascii_composer.cc");if(p.startsWith("recognizer/patterns/"))return new Field("识别规则","对应输入片段的 Boost 正则表达式",STRING,CORE+"gear/recognizer.cc");if(i<0&&!p.isEmpty()){Set<String> components=components(doc,p);if(!components.isEmpty())return new Field(p,"由 engine 中同名命名空间组件使用："+components,MAP,WIKI);}return null;}
    static String[] listChoices(SchemaDocument.Node parent){String p=normalized(parent.path());if(p.equals("engine/processors"))return new String[]{"ascii_composer","recognizer","key_binder","speller","punctuator","selector","navigator","express_editor"};if(p.equals("engine/segmentors"))return new String[]{"ascii_segmentor","matcher","abc_segmentor","affix_segmentor","punct_segmentor","fallback_segmentor"};if(p.equals("engine/translators"))return new String[]{"punct_translator","table_translator","reverse_lookup_translator","script_translator"};if(p.equals("engine/filters"))return new String[]{"simplifier","uniquifier","single_char_filter","reverse_lookup_filter"};return new String[0];}
    static String[] choices(SchemaDocument.Node node){if(node.parent!=null&&node.parent.kind==LIST){String[] options=listChoices(node.parent);if(options.length>0)return options;}String p=normalized(node.path());if(p.equals("speller/auto_clear"))return new String[]{"auto","manual","max_length"};if(p.equals("key_binder/bindings/@/when"))return new String[]{"always","composing","has_menu","paging","predicting"};if(p.startsWith("ascii_composer/switch_key/"))return new String[]{"inline_ascii","commit_text","commit_code","clear","set_ascii_mode","unset_ascii_mode","noop"};return new String[0];}
    static Map<String,Field> patchSuggestions(SchemaDocument doc,SchemaDocument.Node parent){Map<String,Field> result=new LinkedHashMap<>();for(Map.Entry<String,Field> e:fields.entrySet()){String k=e.getKey();Field f=e.getValue();if(k.contains("/@")||k.startsWith("__")||k.startsWith("script_translator/")||k.startsWith("table_translator/")||k.startsWith("affix_segmentor/")||k.startsWith("simplifier/")||f.kind==MAP||k.indexOf('/')<0||parent.child(k)!=null)continue;result.put(k,f);}return result;}
    static Map<String,Field> suggestions(SchemaDocument doc,SchemaDocument.Node parent){String p=normalized(parent.path());Map<String,Field> result=new LinkedHashMap<>();if(parent.kind!=MAP)return result;Set<String> components=components(doc,p);for(Map.Entry<String,Field> e:fields.entrySet()){String k=e.getKey();int i=k.lastIndexOf('/');String group=i<0?"":k.substring(0,i);String name=i<0?k:k.substring(i+1);boolean match=group.equals(p)||components.contains(group);if(!match&&group.equals("translator"))for(String c:components)if(translation(c)){match=true;break;}if(match&&parent.child(name)==null&&!name.equals("@"))result.put(name,e.getValue());}if(parent==doc.root){SchemaDocument.Node engine=doc.root.child("engine");if(engine!=null)for(SchemaDocument.Node l:engine.children)for(SchemaDocument.Node n:l.children){if(!n.scalar())continue;String v=n.value;int i=v.indexOf('@');if(i>0&&i+1<v.length()){String ns=v.substring(i+1);if(parent.child(ns)==null)result.putIfAbsent(ns,new Field(ns,"组件命名空间："+v,MAP,WIKI));}}}return result;}
